 const mMore=(xs,w)=>xs.length>3?`<p class="note">And ${xs.length-3} more behaviour${xs.length===4?'':'s'} ${w} the group${xs.length<=6?': '+join(xs.slice(3).map(x=>esc(x.m.label))):''}.</p>`:'';
 const sHtml=MS.length?(()=>{const seen=new Set();return MS.slice(0,3).map(x=>mItem(x,seen)).join('')+mMore(MS,'above');})():S.length?S.slice(0,3).map(s=>`<div class="item"><b>${L[s.d]} <span class="lab ${cls(s.v.label)}" style="margin-left:4px">${labWord[s.v.label]}</span></b><div class="sm">Above the group as a whole; no single behaviour stands out on three or more looks.</div>${s.quote?quoteHtml(s.quote):''}</div>`).join('')+(S.length>3?`<p class="note">And ${join(S.slice(3).map(s=>L[s.d]))}.</p>`:''):'<p class="muted">Nothing clearly above the group on the evidence so far.</p>';
