 let oHtml=MO.length?(()=>{const seen=new Set();return MO.slice(0,3).map(x=>mItem(x,seen)).join('')+mMore(MO,'below');})():O3.map(o=>`<div class="item"><b>${L[o.d]} <span class="lab ${cls(o.v.label)}" style="margin-left:4px">${labWord[o.v.label]}</span></b>${workOn(o.beh.length?o.beh:o.v.metrics)}${o.quote?quoteHtml(o.quote):''}</div>`).join('')+(O.filter(o=>!o.inside).length>3?`<p class="note">And ${join(O.filter(o=>!o.inside).slice(3).map(o=>L[o.d]))}.</p>`:'');
 if(!MO.length&&!O3.length&&p.focus){const f=p.focus,v=p.descriptors[f.d],wk=v.metrics.filter(m=>m.tag==='weaker'||m.read==='below the group');
  oHtml=`<p class="sm" style="margin:0 0 8px">No behaviour is below the group on three or more looks, so the focus is the lowest of the six.</p><div class="item"><b>${L[f.d]}</b><div class="sm">${cap(f.reason.replace(/^the lowest of the six\s*[-\u2014:]\s*/,''))}.</div>${workOn(wk.length?wk:v.metrics)}${uniqQuotes(v.quotes.filter(q=>q.tone==='-'))[0]?quoteHtml(uniqQuotes(v.quotes.filter(q=>q.tone==='-'))[0]):''}</div>`;}
 const dsc=p.stats&&p.stats.discipline;if(dsc&&dsc.read==='regularly carded')oHtml+=`<div class="item"><b>Discipline <span class="lab LEANM" style="margin-left:4px">Regularly carded</span></b><div class="sm">${dsc.yellows} yellow${dsc.yellows===1?'':'s'} and ${dsc.reds} red${dsc.reds===1?'':'s'} in ${dsc.matches} matches &mdash; more than ${dsc.pctile}% of ${GW(p)} in the same part of the pitch. The timing of challenges, or temperament, is a development point.</div></div>`;
