 const three=`<div class="cols3"><div class="card"><h3>Strengths <small>behaviours above the group</small></h3>${sHtml}</div><div class="card"><h3>Development opportunities <small>behaviours below it</small></h3>${oHtml}</div><div class="card"><h3>Gaps in the evidence</h3>${gHtml}</div></div>`;
 // --- growth
 const rateTxt=m.rate?` <b>Grew ${m.rate.cm} cm in the ${m.rate.months} months to ${MONTH[+m.latest.on.slice(5,7)]} ${m.latest.on.slice(0,4)}</b> &mdash; ${m.rate.cm_per_year} cm a year: ${m.rate.read}.${m.rate.read==='growing fast'?' Co-ordination can dip and come back during fast growth, and training load is worth watching.':''}`:m.n_measurements===1?' Only one height on file: a second, nine months or more apart, would show how fast '+(pl.gender==='F'?'she':'he')+' is growing.':'';
