function workingCard(p,only){const num=(x,dp=2)=>x==null?'<span class="muted">-</span>':Number(x).toFixed(dp);const ds=only?[only]:D;
 return `<div class="card"><h3>From what scouts gave to the score <small>the working: step by step, then look by look</small></h3>
    <table><thead><tr><th>Descriptor</th><th class="num">1. What scouts gave</th><th class="num">2. Who watched and where taken out</th><th class="num">3. Brought to today's age</th><th class="num">Weight of the looks</th><th class="num">4. Leaning toward the age line = estimate</th><th class="num">Score /100</th></tr></thead><tbody>
    ${ds.map(d=>{const v=p.descriptors[d],t=v.steps;if(!t)return '';return `<tr><td><b>${L[d]}</b></td><td class="num">${num(t.raw)}</td><td class="num">${num(t.adjusted)}</td><td class="num">${num(t.today)}</td><td class="num">${Math.round(t.weight*100)}% <span class="muted">= ${v.n_eff}/(${v.n_eff}+1)</span></td><td class="num">${num(t.final)}</td><td class="num"><b>${S100(t.final)}</b></td></tr>`;}).join('')}</tbody></table>
    <p class="note" style="margin:8px 0 10px">Step 4 = age line today + weight &times; (step 3 &minus; age line today). In step 3 recent looks count more (a look from ${M.level_half_life_days===365?'a year':M.level_half_life_days+' days'} ago counts half); each scout has their usual generosity subtracted, and each setting its usual difficulty.</p>
    ${ds.map(d=>{const v=p.descriptors[d],pts=p.series.filter(q=>q[d]);if(!pts.length||!v.steps)return '';const f=M.fits[d];let tot=0;
     const hl=M.level_half_life_days,wt=q=>hl?Math.pow(0.5,Math.max(0,(Date.parse(M.as_of)-Date.parse(q.date))/864e5)/hl):1;let wsum=0;
     const rws=pts.map(q=>{const x=q[d],se=(M.scouts[q.scout]||{adjustment:{}}).adjustment[d]||0,ce=f.context[q.context]||0,left=x.adj-x.bench,w=wt(q);tot+=left*w;wsum+=w;return `<tr><td>${q.date}</td><td>${esc(SN(q.scout))}</td><td>${esc(q.context)}</td><td class="num">${q.age}</td><td class="num">${x.raw}</td><td class="num">${sgn(se.toFixed(2))}</td><td class="num">${sgn(ce.toFixed(2))}</td><td class="num">${x.adj.toFixed(2)}</td><td class="num">${x.bench.toFixed(2)}</td><td class="num"><b>${sgn(left.toFixed(2))}</b></td><td class="num">${Math.round(w*100)}%</td></tr>`;}).join('');
     const mean=tot/wsum;
     return `<details class="bd dd" ${only?'open':''}><summary><b>${L[d]}</b> &mdash; ${plural(pts.length,'look')}, look by look</summary><table style="margin-top:8px"><thead><tr><th>Date</th><th>Scout</th><th>Setting</th><th class="num">Age</th><th class="num">Mark given</th><th class="num">Scout's usual</th><th class="num">Setting's usual</th><th class="num">Mark with both taken out</th><th class="num">Age line then</th><th class="num">Above / below the line</th><th class="num">Counts</th></tr></thead><tbody>${rws}
      <tr style="font-weight:600"><td colspan="9">Average above / below the line over ${plural(pts.length,'look')}, recent looks counting more</td><td class="num">${sgn(mean.toFixed(2))}</td><td></td></tr>
      <tr><td colspan="10">&times; weight ${v.n_eff}/(${v.n_eff}+1) = ${v.R} &rarr; the player's distance from the age line</td><td class="num">${sgn(v.effect)}</td></tr>
      <tr><td colspan="9">+ age line today (age ${p.player.age_now})</td><td class="num">${num(v.base)}</td></tr>
      <tr style="font-weight:700"><td colspan="9">= estimate &rarr; score</td><td class="num">${num(v.estimate)} &rarr; ${S100(v.estimate)}</td></tr></tbody></table></details>`;}).join('')}</div>`;}
