 const stages=['1','2','3','4'].filter(s=>M.cohort.quarter_by_stage[s]);const QC=['#14201A','#4A5A50','#8A948C','#C9D2CB'],TC={early:'#B5731D','on time':'#C9D2CB',late:'#2E6B9E'};
