 const hi=['3','4'].filter(s=>q[s]),h1=hi.reduce((a,s)=>a+q[s].Q1,0),hn=hi.reduce((a,s)=>a+q[s].Q1+q[s].Q2+q[s].Q3+q[s].Q4,0);
